import {newGame,derive,act,tick,restoreSave,PROJECTS} from './engine.js';
import {createScene} from './scene.js';
import {createAudio} from './audio.js';
const $=id=>document.getElementById(id),canvas=$('world'),SAVE='giant-foundry-save-v1',PREFS='giant-foundry-settings-v1';
let state=newGame(),settings={volume:.5,sensitivity:1,quality:matchMedia('(max-width:700px)').matches?'balanced':'high',reduced:matchMedia('(prefers-reduced-motion: reduce)').matches};
try{state=restoreSave(JSON.parse(localStorage.getItem(SAVE)));Object.assign(settings,JSON.parse(localStorage.getItem(PREFS))||{});}catch{}
settings.volume=Number.isFinite(settings.volume)?Math.max(0,Math.min(1,settings.volume)):.5;settings.sensitivity=Number.isFinite(settings.sensitivity)?Math.max(.4,Math.min(2,settings.sensitivity)):1;settings.quality=settings.quality==='balanced'?'balanced':'high';settings.reduced=settings.reduced===true;
const sound=createAudio();sound.setVolume(settings.volume);let world,playing=false,paused=false,walk=false,holding=false,autoPour=false,dragging=false,lastX=0,lastY=0,lastTime=performance.now(),time=0,hudTime=0,saveTime=0,toastTimer,lastFocus;const keys=new Set();
try{world=createScene(canvas,settings);world.resize();world.render(state,.016,0,{reduced:settings.reduced});$('loading').hidden=true;$('start').disabled=false;if(state.cursor>0||state.amount>0)$('start').textContent='Вернуться в мастерскую';}catch(e){$('loading').hidden=true;$('intro').hidden=true;$('error').hidden=false;$('error-message').textContent='Не удалось открыть 3D-сцену. Нужны WebGL 2 и аппаратное ускорение браузера. '+e.message;console.error(e);}
function save(){try{localStorage.setItem(SAVE,JSON.stringify(state));localStorage.setItem(PREFS,JSON.stringify(settings));$('save-status').textContent='Прогресс сохранён';}catch{$('save-status').textContent='Не удалось сохранить';}}
function toast(text){$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3500);}
function clearInput(){holding=false;autoPour=false;dragging=false;keys.clear();}
function syncSettings(){$('volume').value=Math.round(settings.volume*100);$('sensitivity').value=settings.sensitivity;$('quality').value=settings.quality;$('reduced').checked=settings.reduced;$('sound').classList.toggle('muted',settings.volume===0);$('sound').setAttribute('aria-label',settings.volume===0?'Включить звук':'Выключить звук');$('sound').setAttribute('aria-pressed',String(settings.volume>0));sound.setVolume(settings.volume);}
function pause(value){paused=value;$('pause').hidden=!value;$('reset-confirm').hidden=true;if(value){lastFocus=document.activeElement;clearInput();save();$('resume').focus();}else{if(playing)canvas.focus();else lastFocus?.focus();}sound.setActive(playing&&!paused);updateHUD();}
function setWalk(value){walk=value;clearInput();world.setMode(value?'walk':'work');document.body.classList.toggle('walk-mode',value);$('reticle').hidden=!value;$('touch-walk').hidden=!(value&&matchMedia('(pointer:coarse)').matches);$('view-label').textContent=value?'К верстаку':'Прогуляться';canvas.focus();updateHUD();}
function start(){playing=true;$('intro').hidden=true;$('hud').hidden=false;document.body.classList.add('in-game');sound.unlock();sound.setActive(true);world.setMode('work');canvas.focus();if(state.phase==='finished'){setWalk(true);}updateHUD();}
function togglePour(){if(!playing||paused)return;if(walk){setWalk(false);return;}if(state.phase!=='pour')return;autoPour=!autoPour;sound.unlock();canvas.focus();updateHUD();}
function upgrade(){if(!playing||paused||walk)return;const next=act(state,{type:'upgrade'});if(next===state)return;state=next;sound.cue('upgrade');toast(`${derive(state).tool.name} — поток ${derive(state).tool.flow.toLocaleString('ru-RU')} кг/с`);save();updateHUD();}
function nextPart(){const previous=derive(state);state=act(state,{type:'next'});clearInput();if(state.phase==='finished'){$('finish').hidden=false;sound.cue('complete');}else if(previous.part===2){world.resetCamera();toast(`${previous.project.name} теперь на набережной`);}sound.cue('ui');save();updateHUD();canvas.focus();}
function reset(){state=newGame();$('finish').hidden=true;$('reveal-card').hidden=true;clearInput();setWalk(false);if(!playing)world.setMode('intro');save();pause(false);updateHUD();}
$('start').onclick=start;$('settings-button').onclick=()=>pause(true);$('resume').onclick=()=>pause(false);$('pour-toggle').onclick=togglePour;$('upgrade').onclick=upgrade;$('next').onclick=nextPart;$('view-button').onclick=()=>setWalk(!walk);$('camera-reset').onclick=()=>world.resetCamera();
$('sound').onclick=()=>{settings.volume=settings.volume>0?0:.5;sound.unlock();syncSettings();save();};$('volume').oninput=e=>{settings.volume=Number(e.target.value)/100;sound.unlock();syncSettings();save();};$('sensitivity').oninput=e=>{settings.sensitivity=Number(e.target.value);save();};$('quality').onchange=e=>{settings.quality=e.target.value;world.quality(settings.quality);save();};$('reduced').onchange=e=>{settings.reduced=e.target.checked;save();};
$('reset').onclick=()=>{$('reset-confirm').hidden=false;$('reset-no').focus();};$('reset-no').onclick=()=>{$('reset-confirm').hidden=true;$('reset').focus();};$('reset-yes').onclick=reset;$('explore').onclick=()=>{$('finish').hidden=true;setWalk(true);};$('replay').onclick=()=>{$('finish').hidden=true;pause(true);$('reset-confirm').hidden=false;$('reset-no').focus();};
window.addEventListener('keydown',e=>{
 if(e.code==='Escape'){e.preventDefault();pause(!paused);return;}
 if(paused){if(e.code==='Tab'){const focusable=[...$('pause').querySelectorAll('button:not(:disabled),input,select')].filter(el=>!el.closest('[hidden]'));const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}return;}
 if(!playing||!$('finish').hidden||e.target instanceof HTMLInputElement||e.target instanceof HTMLSelectElement)return;
 if(e.code==='Space'&&e.target instanceof HTMLButtonElement)return;
 if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();keys.add(e.code);
 if(e.repeat)return;if(e.code==='Space')togglePour();if(e.code==='KeyG')setWalk(!walk);if(e.code==='KeyE')upgrade();if(e.code==='KeyR')world.resetCamera();
});
window.addEventListener('keyup',e=>keys.delete(e.code));
canvas.addEventListener('contextmenu',e=>e.preventDefault());canvas.addEventListener('pointerdown',e=>{if(!playing||paused||!$('finish').hidden)return;canvas.focus();lastX=e.clientX;lastY=e.clientY;if(e.button===2||e.pointerType==='touch'){dragging=true;canvas.setPointerCapture(e.pointerId);}else if(e.button===0&&!walk){holding=true;sound.unlock();}});
window.addEventListener('pointermove',e=>{if(!playing||paused)return;if(dragging){world.orbit(e.clientX-lastX,e.clientY-lastY,settings.sensitivity);lastX=e.clientX;lastY=e.clientY;}world.aim(e.clientX/innerWidth*2-1,e.clientY/innerHeight*2-1);});
for(const event of ['pointerup','pointercancel'])window.addEventListener(event,()=>{holding=false;dragging=false;});canvas.addEventListener('wheel',e=>{if(!playing||paused||walk)return;e.preventDefault();world.zoom(e.deltaY);},{passive:false});
for(const b of document.querySelectorAll('[data-move]')){b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keys.add(b.dataset.move);});for(const event of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(event,()=>keys.delete(b.dataset.move));}
window.addEventListener('blur',()=>{if(playing&&!paused)pause(true);});document.addEventListener('visibilitychange',()=>{if(document.hidden&&playing){pause(true);save();}});window.addEventListener('pagehide',save);window.addEventListener('resize',()=>world?.resize());canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();save();clearInput();sound.setActive(false);playing=false;$('error').hidden=false;$('error-message').textContent='Графический контекст потерян. Прогресс сохранён. Перезагрузите мастерскую.';});
const format=n=>n.toLocaleString('ru-RU',{maximumFractionDigits:1});
function updateHUD(){const d=derive(state);$('chapter').textContent=['ПЕРВОЕ ТВОРЕНИЕ','ВТОРОЕ ТВОРЕНИЕ','ТРЕТЬЕ ТВОРЕНИЕ'][d.projectIndex];$('project-name').textContent=d.finished?'Мастерская у моря':d.project.name;$('project-subtitle').textContent=d.finished?'Три творения. И начало большого города.':d.project.subtitle;$('chapter-count').textContent=`${state.completed} / 3`;$('overall-progress').style.width=`${d.overall*100}%`;$('stage-name').textContent=d.stageName;$('cast-progress').style.width=`${d.progress*100}%`;$('cast-percent').textContent=`${Math.floor(d.progress*100)}%`;$('stage-counter').textContent=`Часть ${d.part+1} из 3`;$('phase-label').textContent={pour:holding||autoPour?'БРОНЗА ТЕЧЁТ':'ФОРМА ГОТОВА',cool:'МЕТАЛЛ ОСТЫВАЕТ',reveal:'РАСКРЫТИЕ ФОРМЫ',ready:'ОТЛИВКА ГОТОВА',finished:'РАБОТА ЗАВЕРШЕНА'}[state.phase];$('tool-name').textContent=d.tool.name;$('tool-flow').textContent=`${format(d.tool.flow)} кг/с · бронза`;$('credits').textContent=format(state.credits);$('upgrade').disabled=!d.canUpgrade;$('upgrade').classList.toggle('ready',d.canUpgrade);$('upgrade-name').textContent=d.nextTool?d.nextTool.name:'Тигель улучшен';$('upgrade-cost').textContent=d.nextTool?`${format(d.nextTool.cost)} ✧ · улучшить [E]`:'Все улучшения открыты';$('pour-toggle').disabled=!walk&&state.phase!=='pour';$('pour-toggle').setAttribute('aria-pressed',String(autoPour));$('pour-label').textContent=walk?'Вернуться к верстаку':state.phase==='cool'?'Остывает…':state.phase==='reveal'?'Раскрывается…':state.phase==='ready'||d.finished?'Готово':autoPour?'Остановить поток':'Лить бронзу';$('hint').hidden=state.phase==='ready'||d.finished;$('hint-text').textContent=walk?'WASD — ходьба · правая кнопка — обзор':state.phase==='cool'?'Бронза остывает и приобретает свой цвет':state.phase==='reveal'?'Оболочка раскрывается. Ваша работа остаётся.':autoPour?'Поток включён · пробел — остановить':'Удерживайте кнопку мыши или включите постоянный поток';$('reveal-card').hidden=state.phase!=='ready'||walk||!playing;if(state.phase==='ready'){$('reveal-eyebrow').textContent=d.part===2?'НОВОЕ МЕСТО НА НАБЕРЕЖНОЙ':'БРОНЗА ПРИНЯЛА ФОРМУ';$('reveal-title').textContent=d.part===2?d.project.name:d.stageName;$('reveal-text').textContent=d.part===2?d.project.description:`Ещё одна часть вашего творения. +${d.project.rewards[d.part]} ✧ мастерства.`;$('next').textContent=state.cursor===8?'Оживить небесный атлас':d.part===2?'Следующее творение':'Продолжить отливку';}}
function frame(now){const dt=Math.min((now-lastTime)/1000,.08);lastTime=now;if(!paused)time+=dt;const pouring=playing&&!paused&&!walk&&(holding||autoPour)&&state.phase==='pour'&&$('finish').hidden;if(playing&&!paused&&$('finish').hidden){const oldPhase=state.phase;state=tick(state,dt,{pouring});if(oldPhase!==state.phase){if(state.phase==='cool'){clearInput();sound.cue('ui');}if(state.phase==='reveal')sound.cue('open');if(state.phase==='ready'){sound.cue('complete');save();}updateHUD();}if(walk){world.move(Number(keys.has('KeyW'))-Number(keys.has('KeyS')),Number(keys.has('KeyD'))-Number(keys.has('KeyA')),dt);world.orbit((Number(keys.has('ArrowRight'))-Number(keys.has('ArrowLeft')))*dt*220,(Number(keys.has('ArrowDown'))-Number(keys.has('ArrowUp')))*dt*180,settings.sensitivity);}}
 sound.update({pouring,amount:derive(state).progress,heat:state.phase==='cool'?derive(state).heat:pouring?1:0},dt);world?.render(state,paused?0:dt,time,{pouring,reduced:settings.reduced});if(now-hudTime>150){updateHUD();hudTime=now;}if(playing&&now-saveTime>5000){save();saveTime=now;}requestAnimationFrame(frame);}
syncSettings();updateHUD();if(world)requestAnimationFrame(frame);
